// sei-write.mjs <in.ts> <out.ts> [mode]  — mode: both (default) | 608 | 708
// Takes an H.264 TS (the Web Presenter's own recording) and REPLACES the caption SEI of
// every frame with cc_data generated by the app's own encoders, so the result is a
// known-good embedded-caption stream for testing YouTube without the Web Presenter.
// Captions: numbered test lines every ~2.5 s, in CEA-608 roll-up and/or CEA-708 service 1.
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, unlinkSync } from 'node:fs';
import { Cea608Encoder } from '../../../server/cea708/cea608-encoder.js';
import { DtvccEncoder } from '../../../server/cea708/dtvcc-encoder.js';
import { Cea708CdpBuilder } from '../../../server/cea708/cea708-cdp-builder.js';

const [inFile, outFile, mode = 'both'] = process.argv.slice(2);
const tmp = outFile + '.h264';
execFileSync('ffmpeg', ['-y', '-v', 'error', '-i', inFile, '-map', '0:v:0', '-c:v', 'copy', '-bsf:v', 'h264_mp4toannexb', '-f', 'h264', tmp]);
const h264 = readFileSync(tmp);

// ---- caption schedule: one line every 75 frames (2.5 s at 29.97) ----
const FPS = '29.97';
const lines = [];
for (let i = 1; i <= 400; i++) lines.push(`Clean test ${String(i).padStart(3, '0')}: ${mode === '708' ? 'CEA-708 service 1' : mode === '608' ? 'CEA-608 CC1' : '608 and 708'} from ffmpeg, no Web Presenter.`);

const enc608 = new Cea608Encoder();
const enc708 = new DtvccEncoder();
const builder = new Cea708CdpBuilder();

// Per-frame cc_data triplets (A/53 layout = the CDP's ccdata section without header)
function ccDataForFrame(frameIdx) {
    if (frameIdx % 75 === 0) {
        const text = lines[(frameIdx / 75) % lines.length];
        if (mode !== '708') enc608.enqueueText(text);
        if (mode !== '608') enc708.enqueueText(text);
    }
    let cdp;
    if (mode === '608') {
        const p = enc608.drainPair();
        cdp = builder.buildCDP(p.cc1, p.cc2, FPS);
    } else {
        const dt = enc708.drainFrame(builder.dtvccCapacity(FPS));
        const p = mode === '708' ? { cc1: 0x80, cc2: 0x80 } : enc608.drainPair();
        cdp = builder.buildCDP_DTVCC(dt, FPS, p.cc1, p.cc2, mode !== '708');
    }
    // locate ccdata section: byte 7 = 0x72, byte 8 = marker|cc_count, then triplets
    if (cdp[7] !== 0x72) throw new Error('unexpected CDP layout');
    const count = cdp[8] & 0x1F;
    return Buffer.from(cdp.subarray(9, 9 + count * 3));
}

function buildSei(ccData) {
    const count = ccData.length / 3;
    // user_data_registered_itu_t_t35: country B5, provider 0031, 'GA94', user_data_type 03,
    // then process_em_data(1) process_cc_data(1) additional_data(0) cc_count(5), em_data 0xFF,
    // triplets, marker 0xFF
    const payload = Buffer.concat([
        Buffer.from([0xB5, 0x00, 0x31, 0x47, 0x41, 0x39, 0x34, 0x03, 0xC0 | count, 0xFF]),
        ccData,
        Buffer.from([0xFF]),
    ]);
    const body = Buffer.concat([Buffer.from([0x04, payload.length]), payload, Buffer.from([0x80])]);
    // emulation prevention
    const out = [0x06];  // NAL header: nal_ref_idc 0, type 6 (SEI)
    let z = 0;
    for (const b of body) {
        if (z >= 2 && b <= 3) { out.push(3); z = 0; }
        out.push(b);
        z = b === 0 ? z + 1 : 0;
    }
    return Buffer.from(out);
}

// ---- rewrite: drop existing caption SEIs, insert ours before each first slice ----
const starts = [];
for (let p = 0; p + 3 < h264.length; p++) if (h264[p] === 0 && h264[p + 1] === 0 && h264[p + 2] === 1) { starts.push(p + 3); p += 2; }
const nals = starts.map((s, i) => { let e = i + 1 < starts.length ? starts[i + 1] - 3 : h264.length; while (e > s && h264[e - 1] === 0) e--; return h264.subarray(s, e); });

function isCaptionSei(nal) {
    if ((nal[0] & 0x1F) !== 6) return false;
    return nal.includes(Buffer.from('GA94', 'latin1'));
}
const SC = Buffer.from([0, 0, 0, 1]);
const chunks = [];
let frame = 0;
for (const nal of nals) {
    const type = nal[0] & 0x1F;
    if (isCaptionSei(nal)) continue;  // strip the Web Presenter's SEI
    if ((type === 1 || type === 5) && (nal[1] & 0x80)) {
        chunks.push(SC, buildSei(ccDataForFrame(frame)));
        frame++;
    }
    chunks.push(SC, nal);
}
writeFileSync(tmp, Buffer.concat(chunks));
// remux with the original audio if the source has one, else silent AAC (YouTube needs an audio track)
const hasAudio = process.env.KEEP_AUDIO === '1' && execFileSync('ffprobe', ['-v', 'error', '-select_streams', 'a', '-show_entries', 'stream=codec_name', '-of', 'csv=p=0', inFile]).toString().trim().length > 0;
const args = hasAudio
    ? ['-y', '-v', 'error', '-r', '30000/1001', '-i', tmp, '-i', inFile, '-map', '0:v', '-map', '1:a:0', '-c', 'copy', '-f', 'mpegts', outFile]
    : ['-y', '-v', 'error', '-r', '30000/1001', '-i', tmp, '-f', 'lavfi', '-i', 'anullsrc=r=48000:cl=stereo', '-map', '0:v', '-map', '1:a', '-c:v', 'copy', '-c:a', 'aac', '-b:a', '128k', '-shortest', '-f', 'mpegts', outFile];
execFileSync('ffmpeg', args);
unlinkSync(tmp);
console.log(`${outFile}: ${frame} frames, captions every 75 frames, mode ${mode}`);
